export interface Frontmatter {
  title: string;
  date: Date | null;
  tags: string[];
  draft: boolean;
  layout: string;
  slug?: string;
  description?: string;
  [key: string]: unknown;
}

export interface Page {
  /** Path of the source file relative to the source directory. */
  sourcePath: string;
  /** Output path relative to the output directory, e.g. "posts/hello/index.html". */
  outputPath: string;
  /** Site-absolute URL path, e.g. "/posts/hello/". */
  url: string;
  frontmatter: Frontmatter;
  /** Raw markdown body (frontmatter removed). */
  body: string;
  /** Rendered HTML body. */
  html: string;
  /** Plain-text excerpt derived from the body. */
  excerpt: string;
}

export interface SiteConfig {
  sourceDir: string;
  templateDir: string;
  outputDir: string;
  baseUrl: string;
  title: string;
  description: string;
  includeDrafts: boolean;
  clean: boolean;
}

export interface BuildResult {
  pages: Page[];
  tagPages: string[];
  assets: string[];
  outputFiles: string[];
}

export const DEFAULT_CONFIG: SiteConfig = {
  sourceDir: 'content',
  templateDir: 'templates',
  outputDir: 'dist-site',
  baseUrl: 'http://localhost',
  title: 'My Site',
  description: '',
  includeDrafts: false,
  clean: false,
};

import matter from 'gray-matter';
import path from 'node:path';
import type { Frontmatter } from './types.js';

export interface ParsedDocument {
  frontmatter: Frontmatter;
  body: string;
}

function toDate(value: unknown): Date | null {
  if (value instanceof Date) return isNaN(value.getTime()) ? null : value;
  if (typeof value === 'string' || typeof value === 'number') {
    const d = new Date(value);
    return isNaN(d.getTime()) ? null : d;
  }
  return null;
}

function toTags(value: unknown): string[] {
  if (Array.isArray(value)) {
    return value.map((t) => String(t).trim()).filter(Boolean);
  }
  if (typeof value === 'string') {
    return value
      .split(',')
      .map((t) => t.trim())
      .filter(Boolean);
  }
  return [];
}

/** Derive a human-readable title from a file name: "my-first-post.md" -> "My First Post". */
export function titleFromFilename(filePath: string): string {
  const base = path.basename(filePath, path.extname(filePath));
  return base
    .replace(/[-_]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .replace(/\b\w/g, (c) => c.toUpperCase());
}

/**
 * Parse a markdown document with optional YAML frontmatter and normalize
 * the well-known fields (title, date, tags, draft, layout, slug).
 */
export function parseDocument(raw: string, sourcePath = 'untitled.md'): ParsedDocument {
  const { data, content } = matter(raw);

  const frontmatter: Frontmatter = {
    ...data,
    title: typeof data.title === 'string' && data.title.trim() !== ''
      ? data.title.trim()
      : titleFromFilename(sourcePath),
    date: toDate(data.date),
    tags: toTags(data.tags),
    draft: data.draft === true || data.draft === 'true',
    layout: typeof data.layout === 'string' && data.layout.trim() !== ''
      ? data.layout.trim()
      : 'default',
    slug: typeof data.slug === 'string' && data.slug.trim() !== '' ? slugify(data.slug) : undefined,
    description: typeof data.description === 'string' ? data.description : undefined,
  };

  return { frontmatter, body: content };
}

/** Convert an arbitrary string into a URL-safe slug. */
export function slugify(input: string): string {
  return input
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

import MarkdownIt from 'markdown-it';
import hljs from 'highlight.js';

const md: MarkdownIt = new MarkdownIt({
  html: true,
  linkify: true,
  typographer: true,
  highlight(code: string, lang: string): string {
    if (lang && hljs.getLanguage(lang)) {
      const { value } = hljs.highlight(code, { language: lang, ignoreIllegals: true });
      return `<pre><code class="hljs language-${lang}">${value}</code></pre>`;
    }
    const { value } = hljs.highlightAuto(code);
    return `<pre><code class="hljs">${value}</code></pre>`;
  },
});

/** Render markdown to HTML with syntax-highlighted code blocks. */
export function renderMarkdown(markdown: string): string {
  return md.render(markdown);
}

/** Strip markdown/HTML to produce a plain-text excerpt of at most `maxLength` chars. */
export function excerptFrom(markdown: string, maxLength = 200): string {
  const text = renderMarkdown(markdown)
    .replace(/<[^>]+>/g, ' ')
    .replace(/&[a-z#0-9]+;/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  if (text.length <= maxLength) return text;
  return `${text.slice(0, maxLength).replace(/\s+\S*$/, '')}…`;
}

import Handlebars from 'handlebars';
import fs from 'node:fs';
import path from 'node:path';

export interface TemplateEngine {
  /** Render the named layout ("default", "post", ...) with the given context. */
  render(layout: string, context: Record<string, unknown>): string;
  hasLayout(layout: string): boolean;
  layouts(): string[];
}

function formatDate(date: unknown, format?: unknown): string {
  const d = date instanceof Date ? date : new Date(String(date));
  if (isNaN(d.getTime())) return '';
  if (typeof format === 'string' && format === 'iso') return d.toISOString();
  return d.toLocaleDateString('en-US', {
    year: 'numeric',
    month: 'long',
    day: 'numeric',
    timeZone: 'UTC',
  });
}

function registerHelpers(hb: typeof Handlebars): void {
  hb.registerHelper('formatDate', (date: unknown, format: unknown) =>
    formatDate(date, typeof format === 'string' ? format : undefined),
  );
  hb.registerHelper('slugifyTag', (tag: unknown) =>
    String(tag)
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, ''),
  );
  hb.registerHelper('eq', (a: unknown, b: unknown) => a === b);
  hb.registerHelper('limit', (arr: unknown, n: unknown) =>
    Array.isArray(arr) ? arr.slice(0, Number(n)) : [],
  );
}

/**
 * Create a template engine from a directory of Handlebars templates.
 *
 * Layout resolution:
 *   <templateDir>/*.hbs           -> layouts, addressable by basename
 *   <templateDir>/partials/*.hbs  -> registered as partials by basename
 */
export function createTemplateEngine(templateDir: string): TemplateEngine {
  const hb = Handlebars.create();
  registerHelpers(hb);

  const compiled = new Map<string, Handlebars.TemplateDelegate>();

  if (!fs.existsSync(templateDir)) {
    throw new Error(`Template directory not found: ${templateDir}`);
  }

  for (const entry of fs.readdirSync(templateDir, { withFileTypes: true })) {
    if (entry.isFile() && entry.name.endsWith('.hbs')) {
      const name = path.basename(entry.name, '.hbs');
      const src = fs.readFileSync(path.join(templateDir, entry.name), 'utf8');
      compiled.set(name, hb.compile(src));
    }
  }

  const partialsDir = path.join(templateDir, 'partials');
  if (fs.existsSync(partialsDir)) {
    for (const entry of fs.readdirSync(partialsDir, { withFileTypes: true })) {
      if (entry.isFile() && entry.name.endsWith('.hbs')) {
        const name = path.basename(entry.name, '.hbs');
        hb.registerPartial(name, fs.readFileSync(path.join(partialsDir, entry.name), 'utf8'));
      }
    }
  }

  if (!compiled.has('default')) {
    throw new Error(`Template directory must contain a "default.hbs" layout: ${templateDir}`);
  }

  return {
    render(layout: string, context: Record<string, unknown>): string {
      const template = compiled.get(layout) ?? compiled.get('default')!;
      return template(context);
    },
    hasLayout: (layout: string) => compiled.has(layout),
    layouts: () => [...compiled.keys()],
  };
}

import fs from 'node:fs';
import path from 'node:path';
import { parseDocument, slugify } from './frontmatter.js';
import { excerptFrom, renderMarkdown } from './markdown.js';
import type { Page } from './types.js';

function walk(dir: string, base = dir): string[] {
  const results: string[] = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    if (entry.name.startsWith('.')) continue;
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) results.push(...walk(full, base));
    else results.push(path.relative(base, full));
  }
  return results;
}

/** Compute pretty-URL output path for a markdown source path. */
export function outputPathFor(sourcePath: string, slug?: string): string {
  const dir = path.dirname(sourcePath);
  const stem = slug ?? slugify(path.basename(sourcePath, path.extname(sourcePath)));
  const parts = dir === '.' ? [] : dir.split(path.sep);
  if (stem === 'index') return path.posix.join(...parts, 'index.html');
  return path.posix.join(...parts, stem, 'index.html');
}

export function urlFor(outputPath: string): string {
  const url = `/${outputPath.replace(/index\.html$/, '')}`;
  return url === '/' ? '/' : url;
}

/** Load a single markdown file into a Page. */
export function loadPage(sourceDir: string, relPath: string): Page {
  const raw = fs.readFileSync(path.join(sourceDir, relPath), 'utf8');
  const { frontmatter, body } = parseDocument(raw, relPath);
  const outputPath = outputPathFor(relPath.split(path.sep).join('/'), frontmatter.slug);
  return {
    sourcePath: relPath,
    outputPath,
    url: urlFor(outputPath),
    frontmatter,
    body,
    html: renderMarkdown(body),
    excerpt: frontmatter.description ?? excerptFrom(body),
  };
}

export interface LoadedContent {
  pages: Page[];
  /** Non-markdown files to copy through verbatim (relative paths). */
  assets: string[];
}

/** Scan a source directory for markdown pages and static assets. */
export function loadContent(sourceDir: string, includeDrafts: boolean): LoadedContent {
  if (!fs.existsSync(sourceDir)) {
    throw new Error(`Source directory not found: ${sourceDir}`);
  }
  const pages: Page[] = [];
  const assets: string[] = [];
  for (const rel of walk(sourceDir)) {
    if (/\.(md|markdown)$/i.test(rel)) {
      const page = loadPage(sourceDir, rel);
      if (page.frontmatter.draft && !includeDrafts) continue;
      pages.push(page);
    } else {
      assets.push(rel);
    }
  }
  // Newest first; undated pages sort last, ties broken by title.
  pages.sort((a, b) => {
    const ta = a.frontmatter.date?.getTime() ?? -Infinity;
    const tb = b.frontmatter.date?.getTime() ?? -Infinity;
    if (ta !== tb) return tb - ta;
    return a.frontmatter.title.localeCompare(b.frontmatter.title);
  });
  return { pages, assets };
}

import type { Page, SiteConfig } from './types.js';

function escapeXml(input: string): string {
  return input
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;');
}

function absoluteUrl(baseUrl: string, urlPath: string): string {
  return `${baseUrl.replace(/\/+$/, '')}${urlPath}`;
}

/** Generate an RSS 2.0 feed for the newest `limit` dated pages. */
export function generateRss(pages: Page[], config: SiteConfig, limit = 20): string {
  const items = pages
    .filter((p) => p.frontmatter.date !== null)
    .slice(0, limit)
    .map((p) => {
      const link = absoluteUrl(config.baseUrl, p.url);
      const cats = p.frontmatter.tags
        .map((t) => `      <category>${escapeXml(t)}</category>`)
        .join('\n');
      return [
        '    <item>',
        `      <title>${escapeXml(p.frontmatter.title)}</title>`,
        `      <link>${escapeXml(link)}</link>`,
        `      <guid isPermaLink="true">${escapeXml(link)}</guid>`,
        `      <pubDate>${p.frontmatter.date!.toUTCString()}</pubDate>`,
        `      <description>${escapeXml(p.excerpt)}</description>`,
        ...(cats ? [cats] : []),
        '    </item>',
      ].join('\n');
    })
    .join('\n');

  const lastBuildDate = new Date().toUTCString();
  return `<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom">
  <channel>
    <title>${escapeXml(config.title)}</title>
    <link>${escapeXml(config.baseUrl)}</link>
    <description>${escapeXml(config.description)}</description>
    <lastBuildDate>${lastBuildDate}</lastBuildDate>
    <atom:link href="${escapeXml(absoluteUrl(config.baseUrl, '/feed.xml'))}" rel="self" type="application/rss+xml"/>
${items}
  </channel>
</rss>
`;
}

import fs from 'node:fs';
import path from 'node:path';
import { loadContent } from './content.js';
import { slugify } from './frontmatter.js';
import { generateRss } from './rss.js';
import { createTemplateEngine } from './templates.js';
import type { BuildResult, Page, SiteConfig } from './types.js';

interface TagGroup {
  tag: string;
  slug: string;
  pages: Page[];
}

function groupByTag(pages: Page[]): TagGroup[] {
  const groups = new Map<string, TagGroup>();
  for (const page of pages) {
    for (const tag of page.frontmatter.tags) {
      const slug = slugify(tag);
      const group = groups.get(slug) ?? { tag, slug, pages: [] };
      group.pages.push(page);
      groups.set(slug, group);
    }
  }
  return [...groups.values()].sort((a, b) => a.tag.localeCompare(b.tag));
}

function writeFile(outputDir: string, relPath: string, contents: string | Buffer): string {
  const full = path.join(outputDir, relPath);
  fs.mkdirSync(path.dirname(full), { recursive: true });
  fs.writeFileSync(full, contents);
  return relPath;
}

function pageContext(page: Page, site: Record<string, unknown>, pages: Page[]) {
  return {
    site,
    pages,
    page,
    title: page.frontmatter.title,
    date: page.frontmatter.date,
    tags: page.frontmatter.tags,
    description: page.frontmatter.description ?? page.excerpt,
    content: page.html, // use {{{content}}} in layouts
    url: page.url,
  };
}

/** Build the whole site: pages, tag indexes, RSS feed, static assets. */
export function buildSite(config: SiteConfig): BuildResult {
  const engine = createTemplateEngine(config.templateDir);
  const { pages, assets } = loadContent(config.sourceDir, config.includeDrafts);
  const outputFiles: string[] = [];

  if (config.clean && fs.existsSync(config.outputDir)) {
    fs.rmSync(config.outputDir, { recursive: true });
  }
  fs.mkdirSync(config.outputDir, { recursive: true });

  const tagGroups = groupByTag(pages);
  const site = {
    title: config.title,
    description: config.description,
    baseUrl: config.baseUrl,
    tags: tagGroups.map((g) => ({ tag: g.tag, slug: g.slug, count: g.pages.length, url: `/tags/${g.slug}/` })),
  };

  // Content pages.
  for (const page of pages) {
    const html = engine.render(page.frontmatter.layout, pageContext(page, site, pages));
    outputFiles.push(writeFile(config.outputDir, page.outputPath, html));
  }

  // Per-tag index pages (layout "tag", falling back to "default").
  const tagPages: string[] = [];
  for (const group of tagGroups) {
    const rel = path.posix.join('tags', group.slug, 'index.html');
    const html = engine.render('tag', {
      site,
      pages: group.pages,
      tag: group.tag,
      title: `Posts tagged “${group.tag}”`,
      url: `/tags/${group.slug}/`,
    });
    tagPages.push(rel);
    outputFiles.push(writeFile(config.outputDir, rel, html));
  }

  // All-tags index (layout "tags", falling back to "default").
  if (tagGroups.length > 0) {
    const rel = path.posix.join('tags', 'index.html');
    const html = engine.render('tags', { site, title: 'Tags', tags: site.tags, url: '/tags/' });
    tagPages.push(rel);
    outputFiles.push(writeFile(config.outputDir, rel, html));
  }

  // RSS feed.
  outputFiles.push(writeFile(config.outputDir, 'feed.xml', generateRss(pages, config)));

  // Static assets copied through verbatim.
  for (const asset of assets) {
    const src = path.join(config.sourceDir, asset);
    const dest = path.join(config.outputDir, asset);
    fs.mkdirSync(path.dirname(dest), { recursive: true });
    fs.copyFileSync(src, dest);
    outputFiles.push(asset);
  }

  return { pages, tagPages, assets, outputFiles };
}

import chokidar from 'chokidar';
import fs from 'node:fs';
import http from 'node:http';
import path from 'node:path';
import { WebSocketServer, WebSocket } from 'ws';
import { buildSite } from './build.js';
import type { SiteConfig } from './types.js';

const MIME: Record<string, string> = {
  '.html': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.json': 'application/json',
  '.xml': 'application/xml; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.webp': 'image/webp',
  '.ico': 'image/x-icon',
  '.txt': 'text/plain; charset=utf-8',
  '.woff2': 'font/woff2',
};

export function reloadScript(port: number): string {
  return `<script>
(function () {
  function connect() {
    var ws = new WebSocket('ws://' + location.hostname + ':${port}');
    ws.onmessage = function (e) { if (e.data === 'reload') location.reload(); };
    ws.onclose = function () { setTimeout(connect, 1000); };
  }
  connect();
})();
</script>`;
}

/** Inject the live-reload script before </body> (or append if absent). */
export function injectReloadScript(html: string, port: number): string {
  const script = reloadScript(port);
  if (html.includes('</body>')) return html.replace('</body>', `${script}\n</body>`);
  return html + script;
}

export interface DevServer {
  close(): Promise<void>;
  port: number;
}

/** Resolve a request path to a file inside root, guarding against traversal. */
export function resolveRequestPath(root: string, urlPath: string): string | null {
  const decoded = decodeURIComponent(urlPath.split('?')[0] ?? '/');
  let rel = path.posix.normalize(decoded).replace(/^\/+/, '');
  if (rel.startsWith('..')) return null;
  let full = path.resolve(root, rel);
  if (!full.startsWith(path.resolve(root))) return null;
  if (fs.existsSync(full) && fs.statSync(full).isDirectory()) {
    full = path.join(full, 'index.html');
  }
  return fs.existsSync(full) && fs.statSync(full).isFile() ? full : null;
}

/**
 * Start the dev server: initial build, static file serving with reload-script
 * injection, chokidar watching of source + template dirs, WebSocket reloads.
 */
export async function startDevServer(config: SiteConfig, port = 3000): Promise<DevServer> {
  const rebuild = (): void => {
    try {
      const result = buildSite(config);
      // eslint-disable-next-line no-console
      console.log(`[ssgen] built ${result.outputFiles.length} files`);
    } catch (err) {
      console.error('[ssgen] build failed:', err instanceof Error ? err.message : err);
    }
  };
  rebuild();

  const server = http.createServer((req, res) => {
    const file = resolveRequestPath(config.outputDir, req.url ?? '/');
    if (!file) {
      res.writeHead(404, { 'Content-Type': 'text/plain' });
      res.end('Not found');
      return;
    }
    const ext = path.extname(file).toLowerCase();
    const type = MIME[ext] ?? 'application/octet-stream';
    let body: Buffer | string = fs.readFileSync(file);
    if (ext === '.html') {
      body = injectReloadScript(body.toString('utf8'), port);
    }
    res.writeHead(200, { 'Content-Type': type });
    res.end(body);
  });

  const wss = new WebSocketServer({ server });
  const broadcast = (msg: string): void => {
    for (const client of wss.clients) {
      if (client.readyState === WebSocket.OPEN) client.send(msg);
    }
  };

  let timer: NodeJS.Timeout | null = null;
  const watcher = chokidar.watch([config.sourceDir, config.templateDir], {
    ignoreInitial: true,
  });
  watcher.on('all', () => {
    if (timer) clearTimeout(timer);
    timer = setTimeout(() => {
      rebuild();
      broadcast('reload');
    }, 100);
  });

  await new Promise<void>((resolve) => server.listen(port, resolve));
  const address = server.address();
  const actualPort = typeof address === 'object' && address ? address.port : port;
  console.log(`[ssgen] dev server at http://localhost:${actualPort}`);

  return {
    port: actualPort,
    async close(): Promise<void> {
      await watcher.close();
      wss.close();
      await new Promise<void>((resolve, reject) =>
        server.close((err) => (err ? reject(err) : resolve())),
      );
    },
  };
}

#!/usr/bin/env node
import { Command } from 'commander';
import { buildSite } from './build.js';
import { startDevServer } from './server.js';
import { DEFAULT_CONFIG, type SiteConfig } from './types.js';

interface CommonOptions {
  source: string;
  templates: string;
  out: string;
  baseUrl: string;
  title: string;
  description: string;
  drafts: boolean;
  clean: boolean;
}

export function configFromOptions(opts: CommonOptions): SiteConfig {
  return {
    sourceDir: opts.source,
    templateDir: opts.templates,
    outputDir: opts.out,
    baseUrl: opts.baseUrl,
    title: opts.title,
    description: opts.description,
    includeDrafts: opts.drafts,
    clean: opts.clean,
  };
}

function addCommonOptions(cmd: Command): Command {
  return cmd
    .option('-s, --source <dir>', 'source directory of markdown files', DEFAULT_CONFIG.sourceDir)
    .option('-t, --templates <dir>', 'directory of Handlebars templates', DEFAULT_CONFIG.templateDir)
    .option('-o, --out <dir>', 'output directory', DEFAULT_CONFIG.outputDir)
    .option('--base-url <url>', 'absolute base URL for RSS/links', DEFAULT_CONFIG.baseUrl)
    .option('--title <title>', 'site title', DEFAULT_CONFIG.title)
    .option('--description <text>', 'site description', DEFAULT_CONFIG.description)
    .option('--drafts', 'include pages marked draft: true', false)
    .option('--clean', 'remove the output directory before building', false);
}

export function createProgram(): Command {
  const program = new Command();
  program
    .name('ssgen')
    .description('Static site generator: Markdown + YAML frontmatter + Handlebars')
    .version('1.0.0');

  addCommonOptions(
    program
      .command('build')
      .description('Build the site once and exit'),
  ).action((opts: CommonOptions) => {
    const config = configFromOptions(opts);
    const result = buildSite(config);
    console.log(
      `[ssgen] wrote ${result.outputFiles.length} files ` +
        `(${result.pages.length} pages, ${result.tagPages.length} tag pages, ` +
        `${result.assets.length} assets) to ${config.outputDir}`,
    );
  });

  addCommonOptions(
    program
      .command('serve')
      .description('Build, watch, and serve with live reload')
      .option('-p, --port <port>', 'port to listen on', '3000'),
  ).action(async (opts: CommonOptions & { port: string }) => {
    const config = configFromOptions(opts);
    await startDevServer(config, Number(opts.port));
  });

  return program;
}

const isMain = process.argv[1]?.endsWith('cli.ts') || process.argv[1]?.endsWith('cli.js');
if (isMain) {
  createProgram().parseAsync(process.argv).catch((err) => {
    console.error('[ssgen]', err instanceof Error ? err.message : err);
    process.exit(1);
  });
}

